function DataSettings(props: DataProps) {
  const { data, scope, section, refresh } = props, [kind, setKind] = useState(scope === 'global' && section === 'export' ? 'personal' : 'customers'), [job, setJob] = useState<DataJob | null>(null);
  const download = useMutation({ mutationFn: async (value: string) => { const blob = await ownerSettingsApi.export(value); saveBlob(blob, `novya-${value}.json`); }, onSuccess: () => { refresh(); toast.success('Export downloaded'); }, onError: error => toast.error(apiError(error)) });
  const links: [string, string][] = scope === 'global' ? [['export', 'Data & Export'], ['memory', 'Memory & Privacy'], ['security', 'Account Security']] : [['data', 'Data Management'], ['imports', 'Import Customers'], ['exports', 'Exports'], ['jobs', 'Sync Jobs & Errors']];
  if (section === 'imports') return <><SubLinks scope={scope} section={section} links={links} /><CustomerImport refresh={refresh} /></>;
  const jobs = data.jobs.filter(j => section === 'exports' || section === 'export' ? j.kind === 'export' : true);
  return <><SubLinks scope={scope} section={section} links={links} /><div className="ns-stats"><Stat label="Customers" value={data.customers} /><Stat label="Import jobs" value={data.jobs.filter(j => j.kind === 'import').length} /><Stat label="Exports" value={data.jobs.filter(j => j.kind === 'export').length} /><Stat label="Failed deliveries" value={data.outbox.filter(o => o.status === 'failed').length} detail="Recent records" /></div>
    {section === 'jobs' ? <div className="ns-stack"><Card title="Provider event activity" description="Latest events recorded by connected provider adapters.">{data.events.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Provider</th><th>Event</th><th>Status</th><th>Received</th><th>Details</th></tr></thead><tbody>{data.events.map(e => <tr key={e._id}><td>{e.provider}</td><td>{e.kind}</td><td><Badge warn={e.status === 'failed'}>{e.status}</Badge></td><td>{settingsDate(e.createdAt)}</td><td>{e.error || 'No error'}</td></tr>)}</tbody></table></div> : <Empty>No provider events have been received.</Empty>}</Card><Card title="Delivery queue" description="Provider outbox status and retry schedule.">{data.outbox.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Action</th><th>Status</th><th>Attempts</th><th>Next retry</th><th>Error</th></tr></thead><tbody>{data.outbox.map(o => <tr key={o._id}><td>{o.kind}</td><td>{o.status}</td><td>{o.attempts}</td><td>{settingsDate(o.nextAttemptAt)}</td><td>{o.error || 'None'}</td></tr>)}</tbody></table></div> : <Empty>No queued deliveries.</Empty>}<Notice>Delivery retries are managed by the provider worker. Manual replay is unavailable from this dashboard.</Notice></Card></div> : <div className="ns-detail-grid"><Card title={section === 'export' ? 'Export your data' : 'Create export'} description="Download actual records scoped to your account."><div className="ns-fields"><Field label="Export type" value={kind} onChange={setKind} options={scope === 'global' ? ['personal', 'customers', 'business', 'audit'] : ['customers', 'business', 'audit']} /><Field label="Format" value="JSON" onChange={() => undefined} options={['JSON']} /></div><Notice>Exports contain personal information. A sign-in within the last 10 minutes is required before downloading. Tokens, passwords and provider secrets are excluded.</Notice><ErrorMessage error={download.error} /><div className="ns-actions"><Action primary onClick={() => download.mutate(kind)} disabled={download.isPending}><Download size={13} />{download.isPending ? 'Preparing export...' : 'Download export'}</Action></div></Card><Card title="Import customers" description="Upload a CSV file, map columns, validate, then confirm."><DetailList rows={[["Supported records", 'Customers'], ['Maximum file size', '2 MB'], ['Rows per import', '2,000'], ['Marketing consent', 'Off by default']]} /><div className="ns-actions"><Link className="ns-button" href={settingsHref('workspace', 'imports')}>New import<Upload size={12} /></Link></div></Card></div>}
    <Card title="Data job history" description="Latest 100 jobs for this account." className="mt-4">{jobs.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Job</th><th>Type</th><th>Records</th><th>Status</th><th>Created</th><th /></tr></thead><tbody>{jobs.map(j => <tr key={j._id}><td>{j.filename || `Job ${j._id.slice(-6)}`}</td><td>{j.kind}</td><td>{j.total}</td><td><Badge warn={['invalid', 'failed'].includes(j.status)}>{j.status}</Badge></td><td>{settingsDate(j.createdAt)}</td><td><button onClick={() => setJob(j)}>View details</button></td></tr>)}</tbody></table></div> : <Empty>No data jobs yet.</Empty>}</Card>
    {section === 'export' && <Card title="Account data removal" description="Request a reviewed removal of your personal account data." className="mt-4"><Notice>Deleting an owner account can affect the entire business. Submit an erasure request for manual identity and legal-retention review. Creating a request does not immediately delete data.</Notice><div className="ns-actions"><Link className="ns-button" href={settingsHref('workspace', 'privacyRequests')}>Create privacy request</Link></div></Card>}
    <Dialog open={!!job} onOpenChange={open => !open && setJob(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>{job?.filename || 'Data job details'}</DialogTitle><DialogDescription>Stored import or export result.</DialogDescription></DialogHeader><DetailList rows={[["Job ID", job?._id], ['Type', job?.kind], ['Status', job?.status], ['Records', job?.total], ['Imported', job?.imported || 0], ['Completed', settingsDate(job?.completedAt)]]} />{job?.errors?.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Row</th><th>Field</th><th>Issue</th></tr></thead><tbody>{job.errors.map((e, i) => <tr key={i}><td>{e.row}</td><td>{e.field}</td><td>{e.message}</td></tr>)}</tbody></table></div> : null}{job?.kind === 'export' && <Notice>Archives are generated at download time and are not retained on the server. Create another export for current records.</Notice>}</DialogContent></Dialog>
  </>;
}
function CustomerImport({ refresh }: { refresh: () => void }) {
  const [stage, setStage] = useState(0), [filename, setFilename] = useState(''), [headers, setHeaders] = useState<string[]>([]), [rows, setRows] = useState<Record<string, string>[]>([]), [mapping, setMapping] = useState<Record<string, string>>({ name: '', email: '', phone: '', notes: '' }), [result, setResult] = useState<DataJob | null>(null), [error, setError] = useState('');
  const validate = useMutation({ mutationFn: () => ownerSettingsApi.validateImport(filename, rows, Object.fromEntries(Object.entries(mapping).filter(([, v]) => v))), onSuccess: job => { setResult(job); setStage(2); refresh(); }, onError: e => setError(apiError(e)) });
  const run = useMutation({ mutationFn: () => ownerSettingsApi.runImport(result!._id), onSuccess: job => { setResult(job); setStage(3); refresh(); toast.success(`${job.imported} customers imported`); }, onError: e => setError(apiError(e)) });
  async function read(file?: File) {
    setError(''); if (!file) return;
    if (!/\.csv$/i.test(file.name) || file.size > 2 * 1024 * 1024) { setError('Choose a CSV file up to 2 MB.'); return; }
    try { const parsed = parseCustomerCsv(await file.text()); setHeaders(parsed.headers); setRows(parsed.rows); setFilename(file.name); setMapping(Object.fromEntries(['name', 'email', 'phone', 'notes'].map(key => [key, parsed.headers.find(h => h.toLowerCase().replace(/\s/g, '') === key) || (key === 'name' ? parsed.headers.find(h => /full.?name|customer.?name/i.test(h)) || '' : '')]))); setStage(1); setResult(null); } catch (e) { setError(e instanceof Error ? e.message : 'The file could not be read.'); }
  }
  return <><div className="ns-progress">{['1 · Upload file', '2 · Map columns', '3 · Validate records', '4 · Import result'].map((label, i) => <span className={i <= stage ? 'active' : ''} key={label}>{label}</span>)}</div>
    {stage === 0 ? <div className="ns-detail-grid"><Card title="New customer import" description="Upload a UTF-8 CSV file with a header row."><label className="ns-dropzone"><Upload size={30} /><strong>Choose a customer CSV</strong><span className="ns-muted">Up to 2 MB · maximum 2,000 records</span><input aria-label="Choose customer CSV" type="file" accept=".csv,text/csv" onChange={e => void read(e.target.files?.[0])} /></label><div className="ns-actions"><Action onClick={() => saveBlob(new Blob(['name,email,phone,notes\nExample Customer,customer@example.com,+8801700000000,Example note\n'], { type: 'text/csv' }), 'customer-import-template.csv')}><Download size={12} />Download template</Action></div></Card><Card title="Before you import" description="Your existing customers are kept."><DetailList rows={[["Required field", 'Customer name'], ['Optional', 'Email, phone and notes'], ['Duplicates', 'Duplicate email addresses rejected'], ['Consent', 'Marketing disabled'], ['Confirmation', 'Required before records are written']]} /></Card></div> : stage === 1 ? <div className="ns-detail-grid"><Card title="Map customer fields" description={`${filename} · ${rows.length} records detected`}><div className="ns-fields">{Object.keys(mapping).map(key => <Field key={key} label={`${key[0].toUpperCase() + key.slice(1)}${key === 'name' ? ' (required)' : ''}`} value={mapping[key]} onChange={v => setMapping(s => ({ ...s, [key]: v }))} options={['', ...headers]} required={key === 'name'} />)}</div><div className="ns-table-wrap"><table className="ns-table"><thead><tr>{headers.map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.slice(0, 5).map((r, i) => <tr key={i}>{headers.map(h => <td key={h}>{r[h]}</td>)}</tr>)}</tbody></table></div><div className="ns-actions"><Action onClick={() => setStage(0)}>Choose another file</Action><Action primary disabled={!mapping.name || validate.isPending} onClick={() => { setError(''); validate.mutate(); }}>{validate.isPending ? 'Validating...' : 'Validate records'}</Action></div></Card><Card title="Validation checks" description="Validation does not create customers."><DetailList rows={[["Name", 'Required'], ['Email format', 'Validated when provided'], ['Duplicates in file', 'Rejected'], ['Existing emails', 'Rejected'], ['Empty values', 'Allowed for optional fields']]} /></Card></div> : stage === 2 ? <div className="ns-detail-grid"><Card title="Validation results" description={`${filename} · ${result?.total} records`}><Badge warn={result?.status !== 'validated'}>{result?.status === 'validated' ? 'Ready to import' : 'Changes required'}</Badge>{result?.errors?.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>CSV row</th><th>Field</th><th>Issue</th></tr></thead><tbody>{result.errors.map((e, i) => <tr key={i}><td>{e.row}</td><td>{e.field}</td><td>{e.message}</td></tr>)}</tbody></table></div> : <Notice>All records passed validation. Confirm to add {result?.total} customers to your business. Marketing consent will remain off.</Notice>}<div className="ns-actions"><Action onClick={() => { setResult(null); setStage(1); }}>Back to mapping</Action>{result?.status !== 'validated' && <Action onClick={() => setStage(0)}>Upload corrected file</Action>}<Action primary disabled={result?.status !== 'validated' || run.isPending} onClick={() => { setError(''); run.mutate(); }}>{run.isPending ? 'Importing...' : 'Confirm import'}</Action></div></Card><Card title="Import summary"><DetailList rows={[["File", filename], ['Rows', result?.total], ['Validation issues', result?.errors?.length || 0], ['Existing customers', 'Kept'], ['Record type', 'Customer']]} /></Card></div> : <Card title="Import complete" description="Your customers have been saved to your business."><div className="ns-stats"><Stat label="Imported" value={result?.imported || 0} /><Stat label="Total records" value={result?.total || 0} /><Stat label="Status" value="Complete" /><Stat label="Completed" value={settingsDate(result?.completedAt)} /></div><div className="ns-actions"><Action onClick={() => { setStage(0); setRows([]); setResult(null); }}>Import another file</Action><Link className="ns-button primary" href={settingsHref('workspace', 'data')}>View data history</Link></div></Card>}
    {error && <Notice error>{error}</Notice>}
  </>;
}

function PrivacySettings({ data, scope, section, refresh }: DataProps) {
  const [edit, setEdit] = useState<PrivacyRequest | 'new' | null>(null), [search, setSearch] = useState(''), [status, setStatus] = useState('All');
  const rows = data.privacy.filter(p => (status === 'All' || p.status === status) && `${p.subjectName} ${p.subjectEmail} ${p.kind}`.toLowerCase().includes(search.toLowerCase()));
  return <><SubLinks scope={scope} section={section} links={[["privacy", 'Data & Privacy'], ['retention', 'Retention & Residency'], ['consent', 'Consent Management'], ['privacyRequests', 'Privacy Requests']]} /><div className="ns-stats"><Stat label="Open requests" value={data.privacy.filter(p => ['received', 'in_progress'].includes(p.status)).length} /><Stat label="Overdue requests" value={data.privacy.filter(p => ['received', 'in_progress'].includes(p.status) && new Date(p.dueAt) < new Date()).length} /><Stat label="Customer retention" value={`${data.values.retention.customerMonths} mo`} detail="Documented policy" /><Stat label="Consent records" value="Per customer" /></div><Card title="Privacy requests" description="Track customer rights requests. This queue records manual handling; it does not erase or deliver records automatically."><div className="ns-card-top"><input className="ns-input ns-search" placeholder="Search privacy requests..." aria-label="Search privacy requests" value={search} onChange={e => setSearch(e.target.value)} /><select className="ns-input" style={{ maxWidth: 160 }} aria-label="Request status" value={status} onChange={e => setStatus(e.target.value)}>{['All', 'received', 'in_progress', 'completed', 'rejected'].map(v => <option key={v}>{v}</option>)}</select><Action primary onClick={() => setEdit('new')}><Plus size={12} />Create request</Action></div>{rows.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Subject</th><th>Type</th><th>Status</th><th>Due</th><th /></tr></thead><tbody>{rows.map(p => <tr key={p._id}><td>{p.subjectName}<small>{p.subjectEmail}</small></td><td>{p.kind}</td><td><Badge warn={p.status === 'received'}>{p.status.replaceAll('_', ' ')}</Badge></td><td>{settingsDate(p.dueAt)}</td><td><button onClick={() => setEdit(p)}>View request</button></td></tr>)}</tbody></table></div> : <Empty>No privacy requests match your filters.</Empty>}</Card><Dialog open={!!edit} onOpenChange={open => !open && setEdit(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>{edit === 'new' ? 'Create privacy request' : 'Request detail'}</DialogTitle><DialogDescription>Record the request and its manual handling status.</DialogDescription></DialogHeader>{edit && <PrivacyForm request={edit === 'new' ? undefined : edit} done={() => { setEdit(null); refresh(); }} />}</DialogContent></Dialog></>;
}
function PrivacyForm({ request, done }: { request?: PrivacyRequest; done: () => void }) {
  const [values, setValues] = useState({ kind: request?.kind || 'export', subjectName: request?.subjectName || '', subjectEmail: request?.subjectEmail || '', status: request?.status || 'received', note: request?.note || '' });
  const save = useSettingsAction(() => ownerSettingsApi.privacy(values, request?._id), done);
  const set = (key: string, value: string) => setValues(s => ({ ...s, [key]: value }));
  return <form onSubmit={e => { e.preventDefault(); save.mutate(); }}>{request ? <DetailList rows={[["Subject", request.subjectName], ['Email', request.subjectEmail || 'Not entered'], ['Request type', request.kind], ['Due date', settingsDate(request.dueAt)]]} /> : <div className="ns-fields"><Field label="Request type" value={values.kind} onChange={v => set('kind', v)} options={['export', 'erasure', 'rectification', 'restriction']} /><Field label="Subject name" value={values.subjectName} onChange={v => set('subjectName', v)} required /><Field label="Subject email" value={values.subjectEmail} onChange={v => set('subjectEmail', v)} type="email" /></div>}{request && <Field label="Status" value={values.status} onChange={v => set('status', v)} options={['received', 'in_progress', 'completed', 'rejected']} />}<div className="ns-fields"><Field full label="Handling notes" type="textarea" value={values.note} onChange={v => set('note', v)} /></div><Notice>Verify the subject&apos;s identity and complete the request outside this queue before marking it completed. Erasure requests do not automatically delete account or customer data.</Notice><ErrorMessage error={save.error} /><div className="ns-actions"><Action onClick={done}>Cancel</Action>{request && <Action onClick={() => saveBlob(new Blob([JSON.stringify(request, null, 2)], { type: 'application/json' }), `privacy-request-${request._id}.json`)}><Download size={12} />Request record</Action>}<Action primary type="submit" disabled={save.isPending}>Save request</Action></div></form>;
}
function UsageSettings({ data, scope, section, refresh }: DataProps) {
  const [policy, setPolicy] = useState(data.policy || { onLimit: 'pause', monthlyCapEur: 0, overageConsent: false }), [period, setPeriod] = useState(data.counters[0]?.period || new Date().toISOString().slice(0, 7));
  const save = useSettingsAction(() => ownerSettingsApi.billingPolicy(policy), refresh), periods = [...new Set([period, ...data.counters.map(c => c.period)])], rows = data.counters.filter(c => c.period === period);
  return <><SubLinks scope={scope} section={section} links={[["usage", 'Usage & Limits'], ['limits', 'Limit Behavior'], ['audit', 'Audit History']]} /><div className="ns-stats"><Stat label="Plan" value={data.entitlements?.plan || 'Unassigned'} /><Stat label="Entitlement state" value={data.entitlements?.state === 'included' ? 'Included' : 'Restricted'} /><Stat label="Measured counters" value={rows.length} /><Stat label="Measured cost" value={settingsMoney(rows.reduce((sum, r) => sum + r.cost, 0))} /></div>{section === 'limits' ? <form onSubmit={e => { e.preventDefault(); save.mutate(); }}><div className="ns-grid"><Card title="When a limit is reached" description="This policy is read by the backend usage enforcement service."><div className="ns-fields"><Field label="Limit behavior" value={policy.onLimit} onChange={v => setPolicy(s => ({ ...s, onLimit: v }))} options={['pause', 'package', 'overage']} /><Field label="Monthly cap (EUR)" type="number" value={policy.monthlyCapEur} onChange={v => setPolicy(s => ({ ...s, monthlyCapEur: Number(v) }))} min={0} /></div><Toggle label="I explicitly allow paid overage" checked={policy.overageConsent} onChange={v => setPolicy(s => ({ ...s, overageConsent: v }))} /><Notice>Overage requires explicit consent. Purchasing minute packages or add-ons requires a billing provider and is not performed when saving this policy.</Notice></Card><Card title="Current policy"><DetailList rows={[["Behavior", data.policy?.onLimit || 'pause'], ['Monthly cap', settingsMoney(data.policy?.monthlyCapEur || 0)], ['Paid overage', data.policy?.overageConsent ? 'Consented' : 'Not consented']]} /></Card></div><ErrorMessage error={save.error} /><div className="ns-actions"><Action primary type="submit" disabled={save.isPending || !data.organization || (policy.onLimit === 'overage' && !policy.overageConsent)}>Save limit behavior</Action></div></form> : <div className="ns-grid"><Card title="Usage detail" description="Measured usage only. An empty list means there are no recorded usage events for the selected month."><select className="ns-input" style={{ maxWidth: 180 }} aria-label="Usage period" value={period} onChange={e => setPeriod(e.target.value)}>{periods.map(p => <option key={p}>{p}</option>)}</select>{rows.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Metric</th><th>Used</th><th>Cost</th></tr></thead><tbody>{rows.map(r => <tr key={r._id}><td>{r.metric}</td><td>{r.used.toLocaleString()}</td><td>{settingsMoney(r.cost)}</td></tr>)}</tbody></table></div> : <Empty>No recorded usage for {period}.</Empty>}</Card><Card title="Plan limits" description="Limits from your effective versioned subscription.">{data.entitlements && Object.keys(data.entitlements.limits).length ? <DetailList rows={Object.entries(data.entitlements.limits).map(([key, value]) => [key, value === -1 ? 'Unlimited' : value.toLocaleString()])} /> : <Notice>{data.entitlements?.reason || 'No subscription entitlements available.'}</Notice>}<div className="ns-actions"><Link className="ns-button" href={settingsHref('global', 'billing')}>Manage subscription</Link></div></Card></div>}</>;
}
function SecuritySettings({ data, scope, section }: DataProps) {
  const [dialog, setDialog] = useState<'password' | 'revoke' | null>(null), [entry, setEntry] = useState<OwnerSettingsData['audit'][number] | null>(null), [search, setSearch] = useState('');
  const logs = data.audit.filter(a => `${a.action} ${a.section || ''} ${a.detail || ''}`.toLowerCase().includes(search.toLowerCase()));
  return <><SubLinks scope={scope} section={section} links={scope === 'global' ? [['security', 'Account Security'], ['sessions', 'Active Sessions'], ['mfa', 'Two-Factor Authentication'], ['audit', 'Audit Log']] : [['security', 'Business Security'], ['sessions', 'Authentication & Sessions'], ['boundaries', 'Access Boundaries'], ['audit', 'Audit Log']]} /><div className="ns-stats"><Stat label="Two-factor authentication" value={data.profile.mfaEnabled ? 'Enabled' : 'Off'} /><Stat label="Account email" value={data.profile.emailVerified ? 'Verified' : 'Pending'} /><Stat label="Active memberships" value={data.members.filter(m => m.status === 'active').length} /><Stat label="Recent audit entries" value={data.audit.length} /></div>{section === 'mfa' ? <MfaSettings data={data} /> : section === 'audit' ? <Card title="Audit log" description="Recent account actions and security changes. Entries from other businesses are excluded."><input className="ns-input ns-search" aria-label="Search audit log" placeholder="Search audit history..." value={search} onChange={e => setSearch(e.target.value)} />{logs.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Action</th><th>Section</th><th>Time</th><th /></tr></thead><tbody>{logs.map(a => <tr key={a._id}><td>{a.action}</td><td>{a.section || a.category || 'Account'}</td><td>{settingsDate(a.createdAt)}</td><td><button onClick={() => setEntry(a)}>View detail</button></td></tr>)}</tbody></table></div> : <Empty>No matching audit entries.</Empty>}<div className="ns-actions"><Link className="ns-button" href={settingsHref(scope, 'export')}>Export account audit</Link></div></Card> : <div className="ns-grid"><Card title="Sign-in protection" description="Manage your password and authenticator app."><DetailList rows={[["Account", data.profile.email], ['Password', 'Encrypted'], ['Two-factor authentication', data.profile.mfaEnabled ? 'Enabled' : 'Not enabled']]} /><div className="ns-actions"><Action onClick={() => setDialog('password')}>Change password</Action><Link className="ns-button primary" href={settingsHref('global', 'mfa')}>{data.profile.mfaEnabled ? 'Manage' : 'Set up'} two-factor authentication</Link></div></Card><Card title="Authentication & sessions" description="Information from your current authenticated session."><DetailList rows={[["Signed in", settingsDate(data.currentSession.signedInAt)], ['Token expiry', settingsDate(data.currentSession.expiresAt)], ['Session control', 'Revoke all account tokens']]} /><Notice>Per-device sessions are not tracked by the backend. Revoke all sessions to invalidate every account token, including this session.</Notice><div className="ns-actions"><Action danger onClick={() => setDialog('revoke')}>Revoke all sessions</Action></div></Card></div>}<Dialog open={!!dialog} onOpenChange={open => !open && setDialog(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>{dialog === 'password' ? 'Change your password' : 'Revoke all sessions'}</DialogTitle><DialogDescription>After this action you will need to sign in again.</DialogDescription></DialogHeader>{dialog && <SecurityAction kind={dialog} />}</DialogContent></Dialog><Dialog open={!!entry} onOpenChange={open => !open && setEntry(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>Audit entry</DialogTitle><DialogDescription>Stored account activity.</DialogDescription></DialogHeader><DetailList rows={[["Action", entry?.action], ['Section', entry?.section || entry?.category], ['Date', settingsDate(entry?.createdAt)], ['Entry ID', entry?._id]]} /><p className="ns-detail-content">{entry?.detail || 'No additional details recorded.'}</p></DialogContent></Dialog></>;
}
function SecurityAction({ kind }: { kind: 'password' | 'revoke' }) {
  const [currentPassword, setCurrent] = useState(''), [password, setPassword] = useState(''), [confirm, setConfirm] = useState('');
  const save = useMutation({ mutationFn: () => kind === 'password' ? userApi.changePassword({ currentPassword, newPassword: password, confirmNewPassword: confirm }) : ownerSettingsApi.revoke(currentPassword), onSuccess: () => { toast.success('Security updated. Sign in again.'); void signOut({ callbackUrl: '/login' }); } });
  return <form onSubmit={e => { e.preventDefault(); save.mutate(); }}><div className="ns-fields"><Field full type="password" label="Current password" value={currentPassword} onChange={setCurrent} required />{kind === 'password' && <><Field full type="password" label="New password" value={password} onChange={setPassword} required /><Field full type="password" label="Confirm new password" value={confirm} onChange={setConfirm} required /></>}</div>{kind === 'password' && password && password.length < 8 && <Notice>Use at least 8 characters for your new password.</Notice>}<ErrorMessage error={save.error} /><div className="ns-actions"><Action primary type="submit" disabled={save.isPending || !currentPassword || (kind === 'password' && (password.length < 8 || password !== confirm))}>{kind === 'password' ? 'Update password' : 'Revoke all sessions'}</Action></div></form>;
}
function MfaSettings({ data }: { data: OwnerSettingsData }) {
  const [setup, setSetup] = useState<{ secret: string; uri: string } | null>(null), [code, setCode] = useState('');
  const start = useMutation({ mutationFn: ownerSettingsApi.mfaSetup, onSuccess: setSetup });
  const confirm = useMutation({ mutationFn: () => data.profile.mfaEnabled ? ownerSettingsApi.mfaDisable(code) : ownerSettingsApi.mfaConfirm(code), onSuccess: () => { setSetup(null); setCode(''); toast.success('Two-factor authentication updated. Sign in again.'); void signOut({ callbackUrl: '/login' }); } });
  return <div className="ns-detail-grid"><Card title={data.profile.mfaEnabled ? 'Authenticator enabled' : 'Set up two-factor authentication'} description="Use an authenticator app that supports time-based one-time passwords.">{data.profile.mfaEnabled ? <Notice>Enter a fresh code from your authenticator to disable two-factor authentication. All current sessions will be revoked.</Notice> : setup ? <><Notice>In your authenticator, choose &quot;Enter a setup key&quot; and add the secret below. Never share this key.</Notice><DetailList rows={[["Account", data.profile.email], ['Issuer', 'NOVYA'], ['Secret', setup.secret]]} /><p className="ns-muted">Choose time-based codes. Setup expires in 15 minutes.</p></> : <><Notice>A sign-in within the last 10 minutes is required. Your setup is complete only after a valid six-digit code has been confirmed.</Notice><div className="ns-actions"><Action primary onClick={() => start.mutate()} disabled={start.isPending}>Generate setup key</Action></div></>}{(setup || data.profile.mfaEnabled) && <form onSubmit={e => { e.preventDefault(); confirm.mutate(); }}><div className="ns-fields"><Field full label="Six-digit authenticator code" value={code} onChange={v => setCode(v.replace(/\D/g, '').slice(0, 6))} required /></div><div className="ns-actions"><Action primary type="submit" disabled={confirm.isPending || code.length !== 6}>{data.profile.mfaEnabled ? 'Disable authenticator' : 'Verify and enable'}</Action></div></form>}<ErrorMessage error={start.error || confirm.error} /></Card><Card title="Security details"><DetailList rows={[["Current status", data.profile.mfaEnabled ? 'Enabled' : 'Not enabled'], ['Code length', '6 digits'], ['Code period', '30 seconds'], ['Algorithm', 'TOTP SHA-1']]} /><Notice>Recovery codes are not supported by the current authentication service. Keep your authenticator account recovery method secure.</Notice></Card></div>;
}
function CustomFieldsSettings({ data, scope, section, refresh }: DataProps) {
  const [edit, setEdit] = useState<CustomField | 'new' | null>(null), [filter, setFilter] = useState('All');
  const rows = data.fields.filter(f => filter === 'All' || f.entity === filter);
  return <><SubLinks scope={scope} section={section} links={[["customFields", 'Custom Fields'], ['data', 'Data Management']]} /><div className="ns-stats"><Stat label="Defined fields" value={data.fields.length} /><Stat label="Active fields" value={data.fields.filter(f => !f.archived).length} /><Stat label="Record types" value={new Set(data.fields.map(f => f.entity)).size} /><Stat label="Required fields" value={data.fields.filter(f => f.required && !f.archived).length} /></div><Card title="Custom field definitions" description="Create and maintain your own field schema. These definitions are stored for your account."><div className="ns-card-top"><select className="ns-input" style={{ maxWidth: 200 }} aria-label="Filter record type" value={filter} onChange={e => setFilter(e.target.value)}>{['All', 'customer', 'appointment', 'team'].map(v => <option key={v}>{v}</option>)}</select><Action primary onClick={() => setEdit('new')}><Plus size={12} />Create field</Action></div>{rows.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Field</th><th>Record type</th><th>Type</th><th>Status</th><th /></tr></thead><tbody>{rows.map(f => <tr key={f._id}><td>{f.label}<small>{f.key}</small></td><td>{f.entity}</td><td>{f.kind}</td><td><Badge warn={f.archived}>{f.archived ? 'Archived' : f.required ? 'Required' : 'Optional'}</Badge></td><td><button onClick={() => setEdit(f)}>Edit field</button></td></tr>)}</tbody></table></div> : <Empty>No field definitions for this record type.</Empty>}<Notice>Custom values are saved separately on existing customer, appointment and team records. Required fields are validated when saving those values. Creating a definition does not rewrite existing records.</Notice></Card><Dialog open={!!edit} onOpenChange={open => !open && setEdit(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>{edit === 'new' ? 'Create custom field' : 'Edit custom field'}</DialogTitle><DialogDescription>Choose a record type, label and value format.</DialogDescription></DialogHeader>{edit && <CustomFieldForm field={edit === 'new' ? undefined : edit} done={() => { setEdit(null); refresh(); }} />}</DialogContent></Dialog></>;
}
function CustomFieldForm({ field, done }: { field?: CustomField; done: () => void }) {
  const [values, setValues] = useState({ label: field?.label || '', key: field?.key || '', entity: field?.entity || 'customer', kind: field?.kind || 'text', required: field?.required || false, archived: field?.archived || false }), [options, setOptions] = useState(field?.options.join('\n') || '');
  const save = useSettingsAction(() => ownerSettingsApi.field({ ...values, options: values.kind === 'select' ? options.split('\n').map(v => v.trim()).filter(Boolean) : [] }, field?._id), done);
  const set = (key: string, value: string) => setValues(s => ({ ...s, [key]: value }));
  return <form onSubmit={e => { e.preventDefault(); save.mutate(); }}><div className="ns-fields"><Field label="Field label" value={values.label} onChange={v => set('label', v)} required /><Field label="Field key (lowercase letters and _)" value={values.key} onChange={v => set('key', v)} required /><Field label="Record type" value={values.entity} onChange={v => set('entity', v)} options={['customer', 'appointment', 'team']} /><Field label="Value type" value={values.kind} onChange={v => set('kind', v)} options={['text', 'number', 'date', 'checkbox', 'select']} />{values.kind === 'select' && <Field full label="Options (one per line)" type="textarea" value={options} onChange={setOptions} required />}</div><Toggle label="Required field" checked={values.required} onChange={v => setValues(s => ({ ...s, required: v }))} /><Toggle label="Archived" checked={values.archived} onChange={v => setValues(s => ({ ...s, archived: v }))} /><ErrorMessage error={save.error} /><div className="ns-actions"><Action onClick={done}>Cancel</Action><Action primary type="submit" disabled={save.isPending}>Save field</Action></div></form>;
}
function ConnectedAccounts({ data, refresh }: DataProps) {
  const [disconnect, setDisconnect] = useState<string | null>(null);
  const connect = useMutation({ mutationFn: ownerSettingsApi.connectGmail, onSuccess: value => { if (value.authUrl) window.location.assign(value.authUrl); } });
  const remove = useSettingsAction((provider: string) => ownerSettingsApi.disconnectEmail(provider), () => { setDisconnect(null); refresh(); }, 'Email account disconnected');
  return <><div className="ns-grid"><Card title="Connected email services" description="Actual email connections associated with your NOVYA account.">{data.accounts.length ? data.accounts.map(account => <div className="ns-toggle-row" key={account.provider}><div><strong className="capitalize">{account.provider}</strong><p style={{ margin: '4px 0 0' }}>{account.email} · Connected {settingsDate(account.connectedAt)}</p></div><Action onClick={() => setDisconnect(account.provider)}>Disconnect</Action></div>) : <Empty>No email accounts connected.</Empty>}<div className="ns-actions"><Action primary disabled={connect.isPending} onClick={() => connect.mutate()}>Connect Gmail<ArrowRight size={12} /></Action></div><ErrorMessage error={connect.error} /></Card><Card title="Sign-in providers" description="Personal identity and single sign-on."><DetailList rows={[["Password sign-in", 'Available'], ['Authenticator app', data.profile.mfaEnabled ? 'Enabled' : 'Available'], ['Google / Apple / Microsoft sign-in', 'No sign-in adapter configured']]} /><Notice>Email service connections provide mailbox access; they do not add a social sign-in method. Outlook authorization is unavailable because the current backend has no callback implementation.</Notice></Card></div><Dialog open={!!disconnect} onOpenChange={open => !open && setDisconnect(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>Disconnect {disconnect}?</DialogTitle><DialogDescription>This removes the stored email connection from NOVYA. You can also revoke the app in your provider&apos;s security settings.</DialogDescription></DialogHeader><ErrorMessage error={remove.error} /><div className="ns-actions"><Action onClick={() => setDisconnect(null)}>Keep connection</Action><Action danger disabled={remove.isPending} onClick={() => disconnect && remove.mutate(disconnect)}>Disconnect email</Action></div></DialogContent></Dialog></>;
}

function BillingSettings({ data, section, refresh }: DataProps) {
  const params = useSearchParams(), [preview, setPreview] = useState<Awaited<ReturnType<typeof ownerSettingsApi.previewPlan>> | null>(null), [invoice, setInvoice] = useState<OwnerSettingsData['invoices'][number] | null>(null), [checkout, setCheckout] = useState<OwnerSettingsData['plans'][number] | null>(null), [cancel, setCancel] = useState(false);
  const plans = data.plans, current = data.entitlements?.plan || data.subscription?.plan_id?.slug, sub = data.subscription;
  const portal = useMutation({ mutationFn: () => subscriptionApi.portal().then(r => r.data.data as { url: string }), onSuccess: result => window.location.assign(result.url) });
  const planPreview = useMutation({ mutationFn: (slug: string) => ownerSettingsApi.previewPlan(slug, crypto.randomUUID()), onSuccess: setPreview });
  const change = useMutation({ mutationFn: () => ownerSettingsApi.changePlan(preview!._id), onSuccess: result => { toast.success(`Subscription change ${result.status.replaceAll('_', ' ')}`); setPreview(null); refresh(); } });
  const startCheckout = useMutation({ mutationFn: () => subscriptionApi.checkout({ planId: checkout!.checkoutPlanId!, billingCycle: 'monthly' }).then(r => r.data.data as { url: string }), onSuccess: result => window.location.assign(result.url) });
  const cancelPlan = useSettingsAction(() => subscriptionApi.cancel(), () => { setCancel(false); refresh(); }, 'Cancellation submitted to billing provider');
  const confirmCheckout = useSettingsAction(() => subscriptionApi.confirm(params.get('session_id') || ''), refresh, 'Subscription synchronized');
  return <><SubLinks scope="global" section={section} links={[["billing", 'Subscription'], ['billingHistory', 'Billing History'], ['plans', 'Compare Plans']]} />{params.get('status') === 'success' && params.get('session_id') && <Notice>Checkout returned successfully. Verify the provider session to synchronize your subscription.<div className="ns-actions"><Action primary disabled={confirmCheckout.isPending || confirmCheckout.isSuccess} onClick={() => confirmCheckout.mutate()}>Verify subscription</Action></div><ErrorMessage error={confirmCheckout.error} /></Notice>}{params.get('status') === 'cancelled' && <Notice>Checkout was cancelled. No completed payment has been confirmed.</Notice>}
    <div className="ns-stats"><Stat label="Current plan" value={sub?.plan_id?.name || current || 'No plan'} /><Stat label="Subscription status" value={sub?.status?.replaceAll('_', ' ') || 'None'} /><Stat label="Current cycle amount" value={sub ? settingsMoney(sub.amount) : '—'} /><Stat label="Renews / ends" value={settingsDate(sub?.currentPeriodEnd)} /></div>
    {section === 'plans' ? <><div className="ns-plan-grid">{plans.map(plan => <Card key={plan.slug} title={plan.slug} description={current === plan.slug ? 'Your current plan' : plan.isCustom ? 'Custom commercial terms' : 'Monthly subscription'} className="ns-plan"><div><strong>{settingsMoney(plan.monthlyPrice, plan.currency)}</strong><small> / month{plan.isCustom ? ' starting from' : ''}</small></div><ul>{Object.entries(plan.limits).filter(([key]) => ['users', 'locations', 'voiceMinutes', 'whatsappMessages', 'storageGb', 'automations'].includes(key)).map(([key, value]) => <li key={key}>{value === -1 ? 'Unlimited' : value} {key.replace(/([A-Z])/g, ' $1').toLowerCase()}</li>)}</ul>{plan.isCustom ? <Link className="ns-button" href="/support">Contact support</Link> : <Action primary disabled={current === plan.slug || !data.capabilities.stripe || planPreview.isPending || (!data.capabilities.paidSubscription && !plan.checkoutPlanId)} onClick={() => data.capabilities.paidSubscription ? planPreview.mutate(plan.slug) : setCheckout(plan)}>{current === plan.slug ? 'Current plan' : !data.capabilities.stripe || (!data.capabilities.paidSubscription && !plan.checkoutPlanId) ? 'Billing setup required' : data.capabilities.paidSubscription ? 'Preview change' : 'Choose plan'}</Action>}</Card>)}</div><ErrorMessage error={planPreview.error} /><Notice>Prices and plan limits come from the backend versioned catalog. Existing paid subscriptions show a provider preview before a change. A preview may require you to sign in again for fresh authentication.</Notice></> : section === 'billingHistory' ? <Card title="Billing history" description="Invoices recorded for your organization. Provider-only documents remain available in the billing portal.">{data.invoices.length ? <div className="ns-table-wrap"><table className="ns-table"><thead><tr><th>Invoice</th><th>Date</th><th>Amount</th><th>Status</th><th /></tr></thead><tbody>{data.invoices.map(row => <tr key={row._id}><td>{row.invoice_no}</td><td>{settingsDate(row.issuedAt)}</td><td>{settingsMoney(row.total, row.currency)}</td><td><Badge warn={['open', 'overdue'].includes(row.status)}>{row.status}</Badge></td><td><button onClick={() => setInvoice(row)}>View invoice</button></td></tr>)}</tbody></table></div> : <Empty>No invoices recorded.</Empty>}<div className="ns-actions"><Action disabled={!data.capabilities.stripe || portal.isPending} onClick={() => portal.mutate()}>Provider billing portal</Action></div><ErrorMessage error={portal.error} /></Card> : <div className="ns-grid"><Card title="Plan overview" description="The current subscription recorded for your business."><DetailList rows={[["Plan", sub?.plan_id?.name || current || 'No subscription'], ['Status', sub?.status || 'None'], ['Billing cycle', sub?.billingCycle || 'Not started'], ['Current period end', settingsDate(sub?.currentPeriodEnd)], ['Cancellation scheduled', sub?.cancelAtPeriodEnd ? 'Yes' : 'No']]} /><div className="ns-actions"><Link className="ns-button primary" href={settingsHref('global', 'plans')}>Compare plans</Link>{data.capabilities.paidSubscription && <Action danger onClick={() => setCancel(true)} disabled={sub?.cancelAtPeriodEnd}>Cancel renewal</Action>}</div></Card><Card title="Payment & billing" description="Payment details supplied by the billing provider."><DetailList rows={[["Payment method", sub?.paymentMethod?.last4 ? `${sub.paymentMethod.brand} ···· ${sub.paymentMethod.last4}` : 'No payment method recorded'], ['Expiry', sub?.paymentMethod?.expMonth ? `${sub.paymentMethod.expMonth}/${sub.paymentMethod.expYear}` : 'Not recorded'], ['Provider status', data.capabilities.stripe ? 'Configured' : 'Not configured'], ['Recorded invoices', data.invoices.length]]} /><div className="ns-actions"><Link className="ns-button" href={settingsHref('global', 'billingHistory')}>Billing history</Link><Action primary disabled={!data.capabilities.stripe || portal.isPending} onClick={() => portal.mutate()}>Manage payment method</Action></div><ErrorMessage error={portal.error} />{!data.capabilities.stripe && <Notice>The billing provider is not configured. No checkout, plan changes or payment method edits are simulated.</Notice>}</Card></div>}
    <Dialog open={!!preview} onOpenChange={open => !open && setPreview(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>Review subscription change</DialogTitle><DialogDescription>The billing provider preview is valid for 10 minutes.</DialogDescription></DialogHeader><DetailList rows={[["Change", preview?.kind], ['Target plan', preview?.toPlan], ['Effective date', settingsDate(preview?.effectiveAt)], ['Amount due now', preview?.preview.amountDue == null ? 'No immediate provider charge preview' : settingsMoney(preview.preview.amountDue / 100, preview.preview.currency)]]} />{preview?.preview.blockers.length ? <Notice error>Resolve these limits before changing plans: {preview.preview.blockers.map(b => `${b.key}: ${b.current} used, ${b.limit} allowed`).join('; ')}.</Notice> : <Notice>Confirming submits this change to your billing provider. Upgrades may charge immediately; downgrades are scheduled at renewal.</Notice>}<ErrorMessage error={change.error} /><div className="ns-actions"><Action onClick={() => setPreview(null)}>Keep current plan</Action><Action primary disabled={change.isPending || !!preview?.preview.blockers.length} onClick={() => change.mutate()}>Confirm subscription change</Action></div></DialogContent></Dialog>
    <Dialog open={!!checkout} onOpenChange={open => !open && setCheckout(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>Subscribe to {checkout?.slug}</DialogTitle><DialogDescription>Continue to the provider checkout to review and pay.</DialogDescription></DialogHeader><DetailList rows={[["Plan", checkout?.slug], ['Monthly price', checkout ? settingsMoney(checkout.monthlyPrice, checkout.currency) : ''], ['Billing cycle', 'Monthly']]} /><ErrorMessage error={startCheckout.error} /><div className="ns-actions"><Action onClick={() => setCheckout(null)}>Cancel</Action><Action primary disabled={startCheckout.isPending} onClick={() => startCheckout.mutate()}>Continue to checkout</Action></div></DialogContent></Dialog>
    <Dialog open={cancel} onOpenChange={setCancel}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>Cancel subscription renewal?</DialogTitle><DialogDescription>Your subscription stays available until the provider-confirmed current period ends. This does not delete business records.</DialogDescription></DialogHeader><ErrorMessage error={cancelPlan.error} /><div className="ns-actions"><Action onClick={() => setCancel(false)}>Keep subscription</Action><Action danger disabled={cancelPlan.isPending} onClick={() => cancelPlan.mutate()}>Cancel renewal</Action></div></DialogContent></Dialog>
    <Dialog open={!!invoice} onOpenChange={open => !open && setInvoice(null)}><DialogContent className="ns-dialog"><DialogHeader><DialogTitle>{invoice?.invoice_no}</DialogTitle><DialogDescription>Recorded invoice details.</DialogDescription></DialogHeader><DetailList rows={[["Status", invoice?.status], ['Issued', settingsDate(invoice?.issuedAt)], ['Due', settingsDate(invoice?.dueAt)], ['Total', invoice ? settingsMoney(invoice.total, invoice.currency) : '']]} />{invoice?.lines.map((line, i) => <div className="ns-toggle-row" key={i}><span>{line.description} × {line.qty}</span><span>{settingsMoney(line.qty * line.unitPrice, invoice.currency)}</span></div>)}<div className="ns-actions"><Action onClick={() => invoice && saveBlob(new Blob([JSON.stringify(invoice, null, 2)], { type: 'application/json' }), `${invoice?.invoice_no}.json`)}><Download size={12} />Download invoice record</Action></div></DialogContent></Dialog>
  </>;
}

